package main

import "fmt"

const (
	Empty = "."
	X     = "X"
	O     = "O"
)

func printBoard(board [][]string) {
	fmt.Println("  0 1 2")
	for i, row := range board {
		fmt.Printf("%d ", i)
		for _, cell := range row {
			fmt.Printf("%s ", cell)
		}
		fmt.Println()
	}
}

func checkWinner(board [][]string) string {
	for _, row := range board {
		if row[0] != Empty && row[0] == row[1] && row[1] == row[2] {
			return row[0]
		}
	}
	for col := 0; col < 3; col++ {
		if board[0][col] != Empty && board[0][col] == board[1][col] && board[1][col] == board[2][col] {
			return board[0][col]
		}
	}
	if board[0][0] != Empty && board[0][0] == board[1][1] && board[1][1] == board[2][2] {
		return board[0][0]
	}
	return ""
}

func main() {
	// Create 3x3 board
	board := [][]string{
		{Empty, Empty, Empty},
		{Empty, Empty, Empty},
		{Empty, Empty, Empty},
	}

	// Simulate moves
	board[0][0] = X
	board[1][1] = X
	board[2][2] = X
	board[0][2] = O
	board[1][0] = O

	printBoard(board)

	winner := checkWinner(board)
	if winner != "" {
		fmt.Println("Winner:", winner)
	} else {
		fmt.Println("No winner yet")
	}

	// Dynamic 2D slice
	matrix := make([][]int, 4)
	for i := range matrix {
		matrix[i] = make([]int, i+1) // jagged
		for j := range matrix[i] {
			matrix[i][j] = (i + 1) * (j + 1)
		}
	}
	fmt.Println("\nJagged matrix:")
	for _, row := range matrix {
		fmt.Println(row)
	}
}
